<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantConfig\Domain\ValueObject\Accessor\TenantConfigWebauthnRpNameAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantConfigWebauthnRpNameAccessor trait.
 *
 * Covers null default, string/VO assignment via withWebauthnRpName,
 * getWebauthnRpName/webauthnRpName accessors, and isWebauthnRpNameChanged with/without original.
 */
class TenantConfigWebauthnRpNameAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withWebauthnRpName creates a new instance with the WebauthnRpName set
     * from a string value, and getWebauthnRpName returns the primitive string.
     */
    public function testWithWebauthnRpNameFromString(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnRpNameAccessorUnitTest();

        // Act
        $result = $holder->withWebauthnRpName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getWebauthnRpName());
    }
    /**
     * Asserts that withwebauthnRpName has access to the value object
     * from a string value, and getWebauthnRpName returns the primitive string.
     */
    public function testWithWebauthnRpNameFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnRpNameAccessorUnitTest();

        // Act
        $result = $holder->withWebauthnRpName('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->webauthnRpName()->value());
    }
    public function testChangedWebauthnRpName(): void
    {
        // Arrange
        $holder = new ImplWithTenantConfigWebauthnRpNameAccessorUnitTest();
        $original = $holder->withWebauthnRpName('one');
        $same = $holder->withWebauthnRpName('one');
        $modified = $holder->withWebauthnRpName('other');

        // Act
        $unchanged = $holder->isWebauthnRpNameChanged();
        $withSame = $original->isWebauthnRpNameChanged($same);
        $withDiferent = $original->isWebauthnRpNameChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTenantConfigWebauthnRpNameAccessorUnitTest
{
    use TenantConfigWebauthnRpNameAccessor;
}
